import test from 'node:test';
import assert from 'node:assert/strict';
import { lineTotal, invoiceTotals } from '../src/totals.js';

test('lineTotal calculates qty times unitPrice', () => {
  const line = { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 };
  assert.equal(lineTotal(line), 42500);
});

test('lineTotal handles various quantities', () => {
  const line1 = { sku: 'ICON-SET', qty: 10, unitPrice: 980, vatRate: 21 };
  assert.equal(lineTotal(line1), 9800);

  const line2 = { sku: 'STICKER', qty: 1000, unitPrice: 50, vatRate: 21 };
  assert.equal(lineTotal(line2), 50000);
});

test('lineTotal with zero quantity', () => {
  const line = { qty: 0, unitPrice: 8500 };
  assert.equal(lineTotal(line), 0);
});

test('lineTotal with zero unit price', () => {
  const line = { qty: 5, unitPrice: 0 };
  assert.equal(lineTotal(line), 0);
});

test('lineTotal with large numbers', () => {
  const line = { qty: 1000, unitPrice: 1000000 };
  assert.equal(lineTotal(line), 1000000000);
});

test('lineTotal with decimal quantities (edge case)', () => {
  // This tests the behavior when qty is not an integer (though the system should prevent this)
  const line = { qty: 5.5, unitPrice: 8500 };
  assert.equal(lineTotal(line), 46750);
});

test('invoiceTotals calculates discount for single line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 10 }],
  };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 42500, discount: 4250, vat: 8032, voucher: 0, total: 46282 });
});

test('invoiceTotals calculates discount for multiple lines with different rates', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 10 },
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 3, unitPrice: 9500, vatRate: 21, discountPercent: 20 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const expectedSubtotal = 42500 + 28500;
  const expectedDiscount = 4250 + 5700;
  const expectedVat = 8032 + 4788;
  assert.deepEqual(totals, { subtotal: expectedSubtotal, discount: expectedDiscount, vat: expectedVat, voucher: 0, total: expectedSubtotal - expectedDiscount + expectedVat });
});

test('invoiceTotals handles decimal discount percentages', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 12.5 }],
  };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 42500, discount: 5312.5, vat: 7809, voucher: 0, total: 44996.5 });
});

test('invoiceTotals clamps total to 0 if discount exceeds subtotal', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 100 }],
  };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 42500, discount: 42500, vat: 0, voucher: 0, total: 0 });
});

test('invoiceTotals calculates subtotal and total for single line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 0 }],
  };
  const totals = invoiceTotals(invoice);
  // 42500 * 21% = 8925
  assert.deepEqual(totals, { subtotal: 42500, discount: 0, vat: 8925, voucher: 0, total: 51425 });
});

test('invoiceTotals calculates subtotal and total for multiple lines', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 3, unitPrice: 9500, vatRate: 21, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // 42500 * 21% = 8925, 28500 * 21% = 5985, total vat = 14910
  assert.deepEqual(totals, { subtotal: 71000, discount: 0, vat: 14910, voucher: 0, total: 85910 });
});

test('invoiceTotals calculates VAT on amount after discount', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 10 }],
  };
  const totals = invoiceTotals(invoice);
  // lineAmount = 10000, discount = 1000, afterDiscount = 9000, vat = 9000 * 21 / 100 = 1890
  assert.deepEqual(totals, { subtotal: 10000, discount: 1000, vat: 1890, voucher: 0, total: 10890 });
});

test('invoiceTotals handles lines with different VAT rates', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
      { sku: 'PRINT-A4', name: 'Printed flyer A4 (each)', qty: 100, unitPrice: 37, vatRate: 9, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: 42500 * 21% = 8925
  // Line 2: 3700 * 9% = 333
  assert.deepEqual(totals, { subtotal: 46200, discount: 0, vat: 9258, voucher: 0, total: 55458 });
});

test('invoiceTotals handles 0% VAT (VAT exempt)', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'WORKSHOP-DAY', name: 'Brand workshop (day, VAT exempt)', qty: 1, unitPrice: 60000, vatRate: 0, discountPercent: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 60000, discount: 0, vat: 0, voucher: 0, total: 60000 });
});

test('invoiceTotals rounds VAT per line and sums', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'TEST1', name: 'Test 1', qty: 1, unitPrice: 1000, vatRate: 21, discountPercent: 0 },
      { sku: 'TEST2', name: 'Test 2', qty: 1, unitPrice: 2000, vatRate: 21, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: 1000 * 21% = 210
  // Line 2: 2000 * 21% = 420
  // Total VAT = 630 (sum of individually rounded VATs)
  assert.deepEqual(totals, { subtotal: 3000, discount: 0, vat: 630, voucher: 0, total: 3630 });
});

test('invoiceTotals includes voucher in calculation', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 5 }],
    voucher: { code: 'SUMMER2026', amount: 5000 },
  };
  const totals = invoiceTotals(invoice);
  // Base: 42500 - 2125 discount + 8479 VAT = 48854
  // With voucher: 48854 - 5000 = 43854
  assert.deepEqual(totals, { subtotal: 42500, discount: 2125, vat: 8479, voucher: 5000, total: 43854 });
});

test('invoiceTotals returns voucher field (zero if none)', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 5 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.voucher, 0);
  assert.deepEqual(totals, { subtotal: 42500, discount: 2125, vat: 8479, voucher: 0, total: 48854 });
});

test('invoiceTotals clamps total to zero if voucher exceeds total', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 5 }],
    voucher: { code: 'HUGE', amount: 100000 },
  };
