      unitPrice: 1000,
      vatRate: 21,
      discountPercent: 0,
    })),
  };
  const totals = invoiceTotals(invoice);
  // 100 lines * 1000 = 100000
  // VAT: 100000 * 21% = 21000
  assert.equal(totals.subtotal, 100000);
