      { sku: 'C', qty: 10, unitPrice: 500, vatRate: 0, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line A: 10000 - 1000 = 9000 base, 9000 * 21% = 1890
  // Line B: 10000 - 500 = 9500 base, 9500 * 9% = 855
  // Line C: 5000, no VAT
  // subtotal: 25000, discount: 1500, vat: 2745, total: 26245
  assert.equal(totals.subtotal, 25000);
  assert.equal(totals.discount, 1500);
  assert.equal(totals.vat, 2745);
  assert.equal(totals.total, 26245);
});

test('invoiceTotals does not mutate invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 5 }],
  };
  const originalLineCount = invoice.lines.length;
  const originalLineQty = invoice.lines[0].qty;

  invoiceTotals(invoice);
  assert.equal(invoice.lines.length, originalLineCount);
  assert.equal(invoice.lines[0].qty, originalLineQty);
});

test('invoiceTotals works with very small unit prices', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'TINY', qty: 1000000, unitPrice: 1, vatRate: 21, discountPercent: 0 }],
  };
  const totals = invoiceTotals(invoice);
  // 1000000 * 1 = 1000000 cents = €10000
  // VAT: 1000000 * 21% = 210000
  assert.equal(totals.subtotal, 1000000);
  assert.equal(totals.vat, 210000);
  assert.equal(totals.total, 1210000);
});

test('invoiceTotals with rounding edge cases', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'A', qty: 3, unitPrice: 333, vatRate: 21, discountPercent: 0 }, // 999, vat = 209.79 → 210
      { sku: 'B', qty: 3, unitPrice: 334, vatRate: 21, discountPercent: 0 }, // 1002, vat = 210.42 → 210
    ],
  };
  const totals = invoiceTotals(invoice);
  // subtotal: 2001
  // vat: 210 + 210 = 420
  assert.equal(totals.subtotal, 2001);
  assert.equal(totals.vat, 420);
});

test('invoiceTotals preserves decimal precision', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'A', qty: 1, unitPrice: 12345, vatRate: 21, discountPercent: 2.5 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal: 12345
  // discount: 12345 * 2.5% = 308.625
  // base after discount: 12345 - 308.625 = 12036.375
  // vat: 12036.375 * 21% = 2527.6375 → 2528
  assert.equal(totals.subtotal, 12345);
  assert.equal(totals.discount, 308.625);
  assert.equal(totals.vat, 2528);
});

