  customerId: 'C-001',
  issueDate: '2026-10-07',
  lines: [{ sku: 'DES-HOUR', qty: 5 }],
}).value;

const issued = issueInvoice(inv, []).value;
const r = renderInvoiceText(issued);
console.log('render.js works:', r.ok === true);
